import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVAT } from '../src/invoices.js';

test('createInvoice with valid customer, date, and lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 3);
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[1].name, 'Sticker sheet');
  assert.equal(r.value.lines[2].name, 'Brand workshop (day, VAT exempt)');
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' },
  );
});

test('createInvoice rejects invalid date format', () => {
  const invalidDates = [
    '2026/10/07',
    '07-10-2026',
    '2026-10-7',
    '2026-1-07',
    'not a date',
    '2026-10',
    '',
  ];
  for (const date of invalidDates) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: date,
        lines: [{ sku: 'DES-HOUR', qty: 1 }],
      }),
      { ok: false, error: 'DATE_INVALID' },
      `should reject "${date}"`,
    );
  }
});

test('createInvoice rejects invalid dates', () => {
  const invalidDates = [
    '2026-02-30', // Feb doesn't have 30 days
    '2026-04-31', // April has 30 days
    '2026-13-01', // Month 13 doesn't exist
    '2026-00-01', // Month 0 doesn't exist
    '2026-10-00', // Day 0 doesn't exist
  ];
  for (const date of invalidDates) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: date,
        lines: [{ sku: 'DES-HOUR', qty: 1 }],
      }),
      { ok: false, error: 'DATE_INVALID' },
      `should reject invalid date "${date}"`,
    );
  }
});

test('createInvoice accepts valid leap year dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29', // 2024 is a leap year
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
});

test('createInvoice rejects Feb 29 on non-leap year', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-29',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' },
  );
});

test('createInvoice reports NO_LINES for empty array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' },
  );
});

test('createInvoice rejects non-array lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects invalid qty (non-integer)', () => {
  const invalidQtys = [1.5, 0.1, -1, 0, '5', null, undefined];
  for (const qty of invalidQtys) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DES-HOUR', qty }],
      }),
      { ok: false, error: 'QTY_INVALID' },
      `should reject qty ${qty}`,
    );
  }
});

test('createInvoice reports unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' },
  );
});

test('createInvoice stops at first error', () => {
  // Multiple lines, but second one has unknown SKU
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'UNKNOWN', qty: 1 },
      ],
    }),
    { ok: false, error: 'UNKNOWN_SKU' },
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLines = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('createInvoice returns new invoice object', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.notEqual(result1.value, result2.value);
  assert.notEqual(result1.value.lines, result2.value.lines);
  assert.deepEqual(result1.value, result2.value);
});

test('createInvoice includes different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21%
      { sku: 'PRINT-A4', qty: 1 }, // 9%
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0%
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal with zero qty', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('lineTotal returns integer cents', () => {
  const result = lineTotal({ qty: 3, unitPrice: 8500 });
  assert.equal(Number.isInteger(result), true);
  assert.equal(result, 25500);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 }, // 42500
      { qty: 10, unitPrice: 9500 }, // 95000
      { qty: 1, unitPrice: 120000 }, // 120000
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 257500);
  assert.equal(totals.total, 257500);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns object with subtotal and total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(typeof totals, 'object');
  assert.equal(typeof totals.subtotal, 'number');
  assert.equal(typeof totals.total, 'number');
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };
  const originalInvoice = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, originalInvoice);
});

test('lineTotal and invoiceTotals work with created invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 }, // 5 × €85 = €425, 21% VAT = €89.25
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 }, // 3 × €95 = €285, 21% VAT = €59.85
    ],
  });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 71000); // €710
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 14910); // €149.10 = €89.25 + €59.85
  assert.equal(totals.total, 85910); // €710 + €149.10

  assert.equal(lineTotal(r.value.lines[0]), 42500);
  assert.equal(lineTotal(r.value.lines[1]), 28500);
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const result = addLine(r.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
