  assert.equal(goldTotals.discount, 42500); // €425
  assert.equal(goldTotals.vat, 169575); // €1695.75
  assert.equal(goldTotals.total, 977075); // €9770.75

  // Silver: 2.5% discount = €212.50, after disc €8287.50, 21% VAT = €1740.375 ≈ €1740.38
  assert.equal(silverTotals.discount, 21250); // €212.50
  assert.equal(silverTotals.vat, 174038); // €1740.38
  assert.equal(silverTotals.total, 1002788); // €10027.88

  // Standard: 0% discount, 21% VAT = €1785
  assert.equal(standardTotals.discount, 0);
  assert.equal(standardTotals.vat, 178500); // €1785
  assert.equal(standardTotals.total, 1028500); // €10285
});

